139	 * Name: rv1126b_uart5_deassert_reset
140	 *
141	 * Description:
142	 *   De-assert UART5 soft reset via CRU reset registers.
143	 *
144	 ****************************************************************************/
145	
146	static void rv1126b_uart5_deassert_reset(void)
147	{
148	  /* De-assert UART5 presetn and sresetn (SOFTRST_CON05 at BUSCRU + 0xA14)
149	   * Bits 8-9: PRESETN_UART5, SRESETN_UART5.
150	   * Rockchip SOFTRST convention: data 1 asserts reset, data 0 releases
151	   * reset, and the high word selects the affected bits.
152	   */
153	
154	  putreg32(RV1126B_HIWORD_UPDATE(RV1126B_SRST_PRESETN_UART5 |
155	                                 RV1126B_SRST_SRESETN_UART5, 0),
156	           CONSOLE_SOFTRST_REG);
157	}
